import sys
from collections import deque

def bfs(grid, start, end):
    queue = deque([start])
    visited = set()
    visited.add(start)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    while queue:
        x, y = queue.popleft()
        if (x, y) == end:
            return True
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and grid[nx][ny] == 0 and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny))
    return False

n, m, q = map(int, sys.stdin.readline().split())
grid = [[0] * m for _ in range(n)]

for _ in range(q):
    t, r1, c1, r2, c2 = map(int, sys.stdin.readline().split())
    if t == 1:
        for i in range(r1 - 1, r2):
            grid[i][c1 - 1] = 1
            grid[i][c2 - 1] = 1
        for j in range(c1 - 1, c2):
            grid[r1 - 1][j] = 1
            grid[r2 - 1][j] = 1
    elif t == 2:
        for i in range(r1 - 1, r2):
                grid[i][c1 - 1] = 0
                grid[i][c2 - 1] = 0
        for j in range(c1 - 1, c2):
                grid[r1 - 1][j] = 0
                grid[r2 - 1][j] = 0
    elif t == 3:
        if bfs(grid, (r1 - 1, c1 - 1), (r2 - 1, c2 - 1)):
            print("Yes")
        else:
            print("No")
